begin;select plan(7);select ok(to_regclass('public.trust_score_review_requests')is not null,'reviews');select has_function('public','get_my_trust_score_history',array[]::text[]);select has_function('public','request_trust_score_review',array['uuid','text','uuid']);select has_function('public','decide_trust_score_review',array['uuid','text','text','uuid']);select ok(exists(select 1 from pg_indexes where indexname='trust_review_one_open_idx'),'one active review');select ok(not has_table_privilege('anon','private.trust_score_ledger','SELECT'),'trust is private');select ok(exists(select 1 from pg_proc where oid=to_regprocedure('public.decide_trust_score_review(uuid,text,text,uuid)')and prosrc like'%review_compensation%'),'adjustment compensates');select*from finish();rollback;
